<script>$(function(){let filter='all',page=1,timer;const esc=v=>$('<div>').text(v||'N/A').html();function load(){ $.get("{{route('complaints.mobile-list')}}",{filter,page,search:$('#search').val()},function(r){Object.keys(r.counts).forEach(k=>$('#count-'+k).text(r.counts[k]));$('#recordCount').text(r.counts.all+' records');let rows=r.data.map((x,i)=>`<tr><td>${(r.current_page-1)*25+i+1}</td><td>${esc(x.date)}</td><td><a href="${x.detail_url}">${esc(x.number)}</a></td><td>${esc(x.dealer)}</td><td>${esc(x.end_user)}</td><td>${esc(x.mobile)}</td><td>${esc(x.category)}</td><td>${esc(x.size)}</td><td>${esc(x.batch)}</td><td>${esc(x.description)}</td><td>${esc(x.received_through)}</td><td><span class="status-pill">${esc(x.status)}</span></td></tr>`).join('');$('#complaintRows').html(rows);$('#empty').toggle(!r.data.length);$('#prev').prop('disabled',r.current_page<=1);$('#next').prop('disabled',r.current_page>=r.last_page)}).fail(()=>{$('#complaintRows').empty();$('#empty').text('Unable to load complaints').show()})}$('.filter-card').click(function(){filter=$(this).data('filter');page=1;$('.filter-card').removeClass('active');$(this).addClass('active');load()});$('#search').on('input',function(){clearTimeout(timer);timer=setTimeout(()=>{page=1;load()},350)});$('#prev').click(()=>{if(page>1){page--;load()}});$('#next').click(()=>{page++;load()});load()});</script>
